<template><AsyncState :loading="loading" :error="error" :retry-label="t('btn.retry')" @retry="$emit('retry')"><main class="page"><PageHeader :title="t('nav.plugins')"><template #primary><button ref="trigger" data-action="open-create-plugin" @click="open">{{t('plugins.create')}}</button></template></PageHeader><SectionCard><div v-if="plugins.length" class="grid"><article v-for="p in plugins" :key="`${p.name}-${p.path}`"><h3>{{p.displayName||p.name}}</h3><StatusBadge :tone="p.type==='lua'?'warning':'info'">{{p.type==='builtin'?t('plugins.builtin'):p.type}}</StatusBadge><p v-if="p.category">{{p.category}}</p><CopyableValue v-if="p.path" :value="p.path"/></article></div><p v-else>{{t('plugins.empty')}}</p></SectionCard><div v-if="show" class="modal"><form ref="dialog" role="dialog" aria-modal="true" :aria-labelledby="titleId" :aria-describedby="descriptionId" @keydown="onKeydown" @submit.prevent="submit"><h2 :id="titleId">{{t('plugins.create_title')}}</h2><p :id="descriptionId">{{t('plugins.form_name_placeholder')}}</p><label>{{t('plugins.form_name')}}<input ref="input" v-model.trim="name" data-field="plugin-name"/></label><div><button ref="cancel" type="button" data-action="cancel-create-plugin" :disabled="creating" @click="close">{{t('btn.cancel')}}</button><button ref="submitButton" data-action="create-plugin" :disabled="!name||creating">{{t('btn.add')}}</button></div></form></div></main></AsyncState></template>
<script setup>import{nextTick,ref,watch}from'vue';import AsyncState from'../components/AsyncState.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';import StatusBadge from'../components/StatusBadge.vue';const props=defineProps({plugins:{type:Array,default:()=>[]},loading:Boolean,error:{type:[String,Error],default:null},creating:Boolean,t:{type:Function,required:true}});const emit=defineEmits(['create','retry']);const show=ref(false),name=ref(''),trigger=ref(null),dialog=ref(null),input=ref(null),cancel=ref(null),submitButton=ref(null);const titleId='create-plugin-title',descriptionId='create-plugin-description';async function open(){show.value=true;await nextTick();input.value?.focus()}async function close(){if(props.creating)return;show.value=false;name.value='';await nextTick();trigger.value?.focus()}function submit(){if(!name.value||props.creating)return;emit('create',name.value)}function onKeydown(e){if(e.key==='Escape'){e.preventDefault();close();return}if(e.key!=='Tab')return;const first=cancel.value,last=submitButton.value;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}watch(()=>props.creating,(value,old)=>{if(old&&!value&&show.value)close()});</script>
<style scoped>.page{display:grid;gap:16px;min-width:0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(240px,100%),1fr));gap:12px}article{min-width:0;padding:14px;border:1px solid var(--xdev-border-subtle);border-radius:8px}h3{margin:0 0 8px}.modal{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;background:#0009;padding:16px}form{display:grid;gap:16px;width:min(400px,100%);padding:24px;background:var(--xdev-bg-panel);color:var(--xdev-text-primary);border-radius:10px}form h2,form p{margin:0}label{display:grid;gap:6px}input{min-width:0;padding:8px}form div{display:flex;justify-content:flex-end;gap:8px}</style>
